SELECT r.*, w.name AS warehouse_name, ch.name AS channel_name FROM ecom_order_rule r LEFT JOIN wms_warehouse w ON w.id = r.warehouse_id LEFT JOIN ecom_logistics_channel ch ON ch.id = r.channel_id
r.name LIKE CONCAT('%', #{keyword}, '%') AND r.status = #{status}
ORDER BY r.priority, r.id
